actions.script:
boolean d = ec.artifactExecution.disableAuthz()
try {
    def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def tenantList = ec.entity.find("zenith.erp.saas.SaasTenant")
        .condition("organizationPartyId", orgId)
        .condition("statusId", "SaasTenantActive").list()
    if (!tenantList) {
        ec.message.addError("Tenant not found")
        return
    }
    ec.service.sync().name("zenith.saas.SaasServices.change#Plan")
        .parameter("tenantId", tenantList[0].tenantId)
        .parameter("newPlanId", newPlanId)
        .parameter("billingCycle", billingCycle ?: "Monthly")
        .call()
} finally { if (!d) ec.artifactExecution.enableAuthz() }

boolean d = ec.artifactExecution.disableAuthz()
try {
    def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def tenantList = ec.entity.find("zenith.erp.saas.SaasTenant")
        .condition("organizationPartyId", orgId).list()
    if (!tenantList) {
        ec.message.addError("Tenant not found")
        return
    }
    ec.service.sync().name("zenith.saas.SaasServices.cancel#Subscription")
        .parameter("tenantId", tenantList[0].tenantId)
        .parameter("reason", reason ?: "Self-service cancellation")
        .call()
} finally { if (!d) ec.artifactExecution.enableAuthz() }

boolean d = ec.artifactExecution.disableAuthz()
try {
    def invId = ec.web.getRequest().getParameter("saasInvoiceId")
    def _orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def _myTenant = ec.entity.find("zenith.erp.saas.SaasTenant").condition("organizationPartyId", _orgId).list()
    def _inv = ec.entity.find("zenith.erp.saas.SaasInvoice").condition("saasInvoiceId", invId).one()
    if (!_inv || !_myTenant || _inv.tenantId != _myTenant[0].tenantId) {
        ec.web.sendJsonResponse([errors: "Invoice not found for your account."])
        return
    }
    def result = ec.service.sync().name("zenith.saas.SaasPaymentServices.create#RazorpayOrder")
        .parameter("saasInvoiceId", invId).call()
    if (ec.message.hasError()) {
        def msg = ec.message.getErrors().join('; ')
        ec.message.clearErrors()
        ec.web.sendJsonResponse([errors: msg])
        return
    }
    ec.web.sendJsonResponse(result)
} finally { if (!d) ec.artifactExecution.enableAuthz() }

boolean d = ec.artifactExecution.disableAuthz()
try {
    def invId = ec.web.getRequest().getParameter("saasInvoiceId")
    def _orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def _myTenant = ec.entity.find("zenith.erp.saas.SaasTenant").condition("organizationPartyId", _orgId).list()
    def _inv = ec.entity.find("zenith.erp.saas.SaasInvoice").condition("saasInvoiceId", invId).one()
    if (!_inv || !_myTenant || _inv.tenantId != _myTenant[0].tenantId) {
        ec.message.addError("Invoice not found for your account.")
        return
    }
    def result = ec.service.sync().name("zenith.saas.SaasPaymentServices.verify#RazorpayPayment")
        .parameter("razorpay_order_id", ec.web.getRequest().getParameter("razorpay_order_id"))
        .parameter("razorpay_payment_id", ec.web.getRequest().getParameter("razorpay_payment_id"))
        .parameter("razorpay_signature", ec.web.getRequest().getParameter("razorpay_signature"))
        .parameter("saasInvoiceId", ec.web.getRequest().getParameter("saasInvoiceId"))
        .call()
    if (result.success) {
        ec.web.session.setAttribute("moqui.message.validationErrors", null)
        ec.message.addMessage("Payment successful! Your account has been updated.", "success")
    }
} finally { if (!d) ec.artifactExecution.enableAuthz() }

def orgId = ec.user.getPreference("ACTIVE_ORGANIZATION")
context.isSaasManaged = false

if (orgId) {
    boolean wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        def tenantList = ec.entity.find("zenith.erp.saas.SaasTenant")
            .condition("organizationPartyId", orgId)
            .condition("statusId", "SaasTenantActive").list()
        if (tenantList) {
            context.isSaasManaged = true
            def tenant = tenantList[0]
            context.tenantId = tenant.tenantId
            context.tenantName = tenant.tenantName
            context.subdomain = tenant.subdomain

            // Load plan info
            def plan = ec.entity.find("zenith.erp.saas.SaasPlan")
                .condition("planId", tenant.planId).one()
            context.plan = plan

            // ZE-MY-002: the "current" subscription is the ACTIVE (or trialing) one — pick it by
            // STATUS, not by date. change#Plan expires the old sub and creates the new one in the SAME
            // transaction, so both rows share an identical startDate (day-granularity) AND an identical
            // lastUpdatedStamp (same ms) — a dead tie that let the dashboard grab the just-expired sub
            // (showing "Expired / 0" right after an upgrade). Prefer SubActive/SubTrial; fall back to the
            // most recent of any status only when the tenant has no live subscription.
            def subList = ec.entity.find("zenith.erp.saas.SaasSubscription")
                .condition("tenantId", tenant.tenantId)
                .condition("statusId", "in", ["SubActive", "SubTrial"])
                .orderBy("-startDate").orderBy("-lastUpdatedStamp").limit(1).list()
            if (!subList) {
                subList = ec.entity.find("zenith.erp.saas.SaasSubscription")
                    .condition("tenantId", tenant.tenantId)
                    .orderBy("-startDate").orderBy("-lastUpdatedStamp").limit(1).list()
            }
            context.subscription = subList ? subList[0] : null

            // Load allowed modules
            def planModules = ec.entity.find("zenith.erp.saas.SaasPlanModule")
                .condition("planId", tenant.planId).list()
            context.moduleList = planModules

            // ZE-MY-001: Count users in this tenant. Must match the "Users & Role Assignment" screen,
            // which scopes a tenant's users by its TENANT_* user group (the org anchor) — NOT by
            // PartyRelationship(OrgInternal). Most users added via Settings > Create User never got that
            // relationship, so the old count undercounted (showed 1 when 3 users existed). Count DISTINCT
            // non-disabled accounts (a disabled user can't log in, so it frees a seat).
            def _tenantGroups = ec.entity.find("moqui.security.UserGroupMember")
                .condition("userId", ec.user.userId).list()*.userGroupId.findAll { it?.startsWith('TENANT_') }.unique()
            def _uids = (_tenantGroups
                ? ec.entity.find("moqui.security.UserGroupMember").condition("userGroupId", "in", _tenantGroups).list()*.userId
                : ec.entity.find("moqui.security.UserPreference").condition("preferenceKey", "ACTIVE_ORGANIZATION")
                    .condition("preferenceValue", orgId).list()*.userId) as Set
            _uids << ec.user.userId   // the viewer always counts
            int _activeUsers = 0
            if (_uids) {
                ec.entity.find("moqui.security.UserAccount").condition("userId", "in", new ArrayList(_uids)).list().each {
                    if (it.disabled != 'Y') _activeUsers++
                }
            }
            context.userCount = _activeUsers

            // Plan limits
            context.maxUsers = plan?.maxUsers ?: 0
            context.maxPos = plan?.maxPosTerminals ?: 0
            context.maxProducts = plan?.maxProductsSku ?: 0
            context.maxTxn = plan?.maxMonthlyTransactions ?: 0
            context.maxStores = plan?.maxStores ?: 0
            context.maxLoyalty = plan?.maxLoyaltyMembers ?: 0
            context.maxPromos = plan?.maxPromotions ?: 0
            // Actual org-scoped usage (entity filters scope these to the tenant)
            try {
                context.usedProducts = ec.entity.find("mantle.product.Product").condition("productTypeEnumId","PtAsset").condition("ownerPartyId", orgId).count() as int
                context.usedTerminals = ec.entity.find("zenith.erp.pos.PosTerminal").condition("organizationPartyId", orgId).count() as int
                def _ms = java.sql.Timestamp.valueOf(new java.text.SimpleDateFormat("yyyy-MM").format(ec.user.nowTimestamp) + "-01 00:00:00")
                context.usedTxn = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", orgId).condition("entryDate",">=",_ms).count() as int
            } catch (Exception _e) { context.usedProducts = 0; context.usedTerminals = 0; context.usedTxn = 0 }

            // Pending invoices
            def invList = ec.entity.find("zenith.erp.saas.SaasInvoice")
                .condition("tenantId", tenant.tenantId)
                .condition("statusId", "in", ["SiSent", "SiOverdue"])
                .orderBy("-invoiceDate").list()
            context.pendingInvoices = invList

            // Razorpay key for client-side checkout
            def rzpKey = ec.entity.find("zenith.erp.base.CompanySettings")
                .condition("organizationPartyId", "ZETAERP")
                .condition("settingKey", "RAZORPAY_KEY_ID").one()
            context.razorpayKeyId = rzpKey?.settingValue ?: ''

            // Payment history
            def payHistory = ec.entity.find("zenith.erp.saas.SaasPayment")
                .condition("tenantId", tenant.tenantId)
                .orderBy("-paymentDate").limit(10).list()
            context.paymentHistory = payHistory

            // All plans for upgrade comparison
            def allPlans = ec.entity.find("zenith.erp.saas.SaasPlan")
                .condition("isActive", "Y").orderBy("sortOrder").list()
            context.allPlans = allPlans
            context.currentPlanSortOrder = plan?.sortOrder ?: 0

            // ===== My Subscription redesign (My_subscription.png) — display chrome built here =====
            // ZE-MY-003: extra org-scoped usage counts (reuse the update#TenantUsage patterns + field traps:
            // Store scopes by organizationPartyId + statusId (NO isActive); LoyaltyMember has no org field so
            // use the org-scoped LoyaltyMemberDetail view; Promotion uses organizationPartyId + isActive='Y').
            try { context.usedStores = ec.entity.find("zenith.erp.stores.Store").condition("organizationPartyId", orgId).condition("statusId","!=","StClosed").count() as int } catch (Exception _es) { context.usedStores = 0 }
            try { context.usedLoyalty = ec.entity.find("zenith.erp.loyalty.LoyaltyMemberDetail").condition("organizationPartyId", orgId).condition("statusId","LmActive").count() as int } catch (Exception _el) { context.usedLoyalty = 0 }
            try { context.usedPromos = ec.entity.find("zenith.erp.promotions.Promotion").condition("organizationPartyId", orgId).condition("isActive","Y").count() as int } catch (Exception _ep) { context.usedPromos = 0 }

            def sub = context.subscription
            context.trialDaysLeft = 0
            if (sub?.trialEndDate) { def _msLeft = sub.trialEndDate.getTime() - ec.user.nowTimestamp.getTime(); context.trialDaysLeft = _msLeft > 0 ? (int)Math.ceil(_msLeft / 86400000.0d) : 0 }
            // back link — stay on the current surface (/apps or /qapps): trim requestURI to the zenith app root
            try { def _u = ec.web?.getRequest()?.getRequestURI() ?: ''; def _zi = _u.indexOf('/zenith'); context.homeBase = _zi >= 0 ? _u.substring(0, _zi + 7) : '/apps/zenith' } catch (Exception _eu) { context.homeBase = '/apps/zenith' }

            def Z = com.zenith.Fmt.INSTANCE
            def _at = 'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" fill="none"'
            def _s18 = { String pp -> '<svg width="18" height="18" viewBox="0 0 24 24" ' + _at + '>' + pp + '</svg>' }
            def svgCrown = '<svg width="26" height="26" viewBox="0 0 24 24" ' + _at + '><path d="M11.562 3.266a.5.5 0 0 1 .876 0L15.39 8.87a1 1 0 0 0 1.516.294L21.183 5.5a.5.5 0 0 1 .798.519l-2.834 10.246a1 1 0 0 1-.956.734H5.81a1 1 0 0 1-.957-.734L2.02 6.02a.5.5 0 0 1 .798-.519l4.276 3.664a1 1 0 0 0 1.516-.294z"/><path d="M5 21h14"/></svg>'
            def svgCal = _s18('<path d="M8 2v3"/><path d="M16 2v3"/><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/>')
            def svgRefresh = _s18('<path d="M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8"/><path d="M21 3v5h-5"/><path d="M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16"/><path d="M8 16H3v5"/>')
            def svgCard = _s18('<rect width="20" height="14" x="2" y="5" rx="2"/><line x1="2" x2="22" y1="10" y2="10"/>')
            def svgUsers = _s18('<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><path d="M16 3.128a4 4 0 0 1 0 7.744"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>')
            def svgMonitor = _s18('<rect width="20" height="14" x="2" y="3" rx="2"/><line x1="8" x2="16" y1="21" y2="21"/><line x1="12" x2="12" y1="17" y2="21"/>')
            def svgPackage = _s18('<path d="M11 21.73a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73z"/><path d="M12 22V12"/><polyline points="3.29 7 12 12 20.71 7"/><path d="m7.5 4.27 9 5.15"/>')
            def svgFile = _s18('<path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/><path d="M14 2v5a1 1 0 0 0 1 1h5"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/>')
            def svgStore = _s18('<path d="M15 21v-5a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v5"/><path d="M17.774 10.31a1.12 1.12 0 0 0-1.549 0 2.5 2.5 0 0 1-3.451 0 1.12 1.12 0 0 0-1.548 0 2.5 2.5 0 0 1-3.452 0 1.12 1.12 0 0 0-1.549 0 2.5 2.5 0 0 1-3.77-3.248l2.889-4.184A2 2 0 0 1 7 2h10a2 2 0 0 1 1.653.873l2.895 4.192a2.5 2.5 0 0 1-3.774 3.244"/><path d="M4 10.95V19a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8.05"/>')
            def svgMega = _s18('<path d="M11 6a13 13 0 0 0 8.4-2.8A1 1 0 0 1 21 4v12a1 1 0 0 1-1.6.8A13 13 0 0 0 11 14H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2z"/><path d="M6 14a12 12 0 0 0 2.4 7.2 2 2 0 0 0 3.2-2.4A8 8 0 0 1 10 14"/><path d="M8 6v8"/>')

            // current plan summary card
            def _pName = (plan?.planName ?: 'N/A')
            def _stId = sub?.statusId
            def _stLbl = _stId == null ? '' : (_stId == 'SubActive' ? 'Active' : _stId == 'SubTrial' ? 'Trial' : _stId == 'SubExpired' ? 'Expired' : _stId == 'SubCancelled' ? 'Cancelled' : _stId == 'SubPastDue' ? 'Past Due' : _stId)
            def _stCls = (_stId == 'SubActive' || _stId == 'SubTrial') ? 'mysub-badge-active' : 'mysub-badge-inactive'
            def _meta = new StringBuilder()
            if (sub?.trialEndDate) { _meta.append('<div class="mysub-meta">').append(svgCal).append('<div><span class="mysub-meta-label">Trial ends on</span><span class="mysub-meta-val">').append(ec.l10n.format(sub.trialEndDate,'dd-MMM-yyyy')).append('</span><span class="mysub-meta-help">(').append(context.trialDaysLeft).append(' days left)</span></div></div>') }
            if (sub?.renewalDate) { _meta.append('<div class="mysub-meta">').append(svgRefresh).append('<div><span class="mysub-meta-label">Next renewal</span><span class="mysub-meta-val">').append(ec.l10n.format(sub.renewalDate,'dd-MMM-yyyy')).append('</span></div></div>') }
            def _bAmt = sub?.amount != null ? sub.amount : (plan?.monthlyPrice ?: 0)
            def _bCur = sub?.currencyUomId ?: 'INR'
            def _bCyc = sub?.billingCycle ?: 'Monthly'
            _meta.append('<div class="mysub-meta">').append(svgCard).append('<div><span class="mysub-meta-label">Billing</span><span class="mysub-meta-val">').append(_bCur).append(' ').append(Z.inr(ec.l10n.format(_bAmt,'#,##0'))).append(' / ').append(_bCyc).append('</span></div></div>')
            context.currentPlanHtml = '<div class="mysub-cp-card"><div class="mysub-cp-row"><div class="mysub-cp-left"><div class="mysub-cp-avatar">' + svgCrown + '</div><div><span class="mysub-cp-label">Current Plan</span><div class="mysub-cp-namerow"><span class="mysub-cp-name">' + _pName + '</span>' + (_stLbl ? ('<span class="' + _stCls + '">' + _stLbl + '</span>') : '') + '</div></div></div><div class="mysub-cp-meta">' + _meta.toString() + '</div></div></div>'

            // usage grid
            def _urow = { String svg, String lbl, def used, def mx ->
                def _u = (used ?: 0) as long
                def _m = (mx ?: 0) as long
                def _mStr = _m == 0 ? 'Unlimited' : Z.inr(ec.l10n.format(_m,'#,##0'))
                def _uStr = Z.inr(ec.l10n.format(_u,'#,##0'))
                def _pct = _m > 0 ? Math.min(100L, Math.round(_u * 100.0d / _m)) : 4
                return '<div class="mysub-urow"><div class="mysub-urow-top">' + svg + '<span class="mysub-ulabel">' + lbl + '</span><span class="mysub-uval">' + _uStr + ' <span class="mx">/ ' + _mStr + '</span></span></div><div class="mysub-bar"><div class="mysub-bar-fill" style="width:' + _pct + '%"></div></div></div>'
            }
            context.usageHtml = '<div class="mysub-usage-grid">' +
                _urow(svgUsers, 'Users', context.userCount, context.maxUsers) +
                _urow(svgMonitor, 'POS Terminals', context.usedTerminals, context.maxPos) +
                _urow(svgPackage, 'Products', context.usedProducts, context.maxProducts) +
                _urow(svgFile, 'Monthly Transactions', context.usedTxn, context.maxTxn) +
                _urow(svgStore, 'Stores', context.usedStores, context.maxStores) +
                _urow(svgUsers, 'Loyalty Members', context.usedLoyalty, context.maxLoyalty) +
                _urow(svgMega, 'Active Promotions', context.usedPromos, context.maxPromos) +
                '</div>'
        }
    } catch (Exception e) { /* SaaS entities may not exist */ }
    finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
}
